enum Direction {
    North,
    South,
    East,
    West,
}

fn main() {
    let heading = Direction::North;
    match heading {
        Direction::North => println!("going up"),
        Direction::South => println!("going down"),
        Direction::East => println!("going right"),
        Direction::West => println!("going left"),
    }
}

enum Shape {
    Circle { radius: f64 },
    Point(i32, i32),
}

fn main() {
    let shapes = [
        Shape::Circle { radius: 2.0 },
        Shape::Point(3, -1),
    ];

    for s in shapes {
        match s {
            Shape::Circle { radius } => println!("circle of radius {radius}"),
            Shape::Point(x, y) => println!("point at {x}, {y}"),
        }
    }
}

fn main() {
    let n = 7;

    match n {
        0 => println!("zero"),
        1 => println!("one"),
        2..=5 => println!("a few"),
        other => println!("something else: {other}"),
    }

    let flag = false;
    match (n, flag) {
        (7, _) => println!("seven, whatever the flag is"),
        _ => println!("not seven"),
    }
}

fn main() {
    let age: Option<i32> = Some(30);
    let missing: Option<i32> = None;

    match age {
        Some(n) => println!("age is {n}"),
        None => println!("no age recorded"),
    }

    if let Some(n) = missing {
        println!("age is {n}");
    } else {
        println!("still no age recorded");
    }

    println!("default to {}", missing.unwrap_or(0));
}

fn main() {
    let mut pending = Some(3);

    while let Some(n) = pending {
        println!("working on {n}");
        pending = if n > 1 { Some(n - 1) } else { None };
    }

    println!("nothing left");
}

